// Parse Google News RSS + Reddit to find the best trending topic
const news = $('📰 Google News RSS (Plant)').item.json;
const reddit = $('🔴 Reddit r/houseplants').item.json;

// Extract news titles from RSS XML
const rssBody = typeof news === 'string' ? news : JSON.stringify(news);
const newsTitles = [];
const titleMatches = rssBody.match(/<title><![CDATA[(.*?)]]><\/title>/g) || 
                    rssBody.match(/<title>(.*?)<\/title>/g) || [];
for (const m of titleMatches.slice(1, 6)) {
  const title = m.replace(/<[^>]+>/g, '').replace(/<!\/CDATA|CDATA\[|]]>/g, '').trim();
  if (title && title.length > 10) newsTitles.push(title);
}

// Extract Reddit top posts
const redditTopics = [];
try {
  const posts = reddit.data?.children || [];
  for (const p of posts.slice(0, 5)) {
    const title = p.data?.title || '';
    const score = p.data?.score || 0;
    if (title && score > 50) redditTopics.push(`${title} (${score} upvotes)`);
  }
} catch(e) {}

// Combine for Gemini context
const context = [
  'TRENDING GOOGLE NEWS:', ...newsTitles.slice(0, 3),
  'TRENDING REDDIT:', ...redditTopics.slice(0, 3)
].join('\n');

// Fallback topics if no fresh trends found
const fallbacks = [
  'Why Your Monstera Leaves Are Turning Yellow (And How to Fix It)',
  'Spider Mites on Houseplants: The Complete Elimination Guide',
  'Overwatering vs Underwatering: How to Tell the Difference',
  'The Best Soil Mix for Tropical Plants in 2026',
  'Root Rot: How to Save a Dying Plant in 7 Steps'
];

const hasFreshTrends = newsTitles.length > 0 || redditTopics.length > 0;

return {
  trend_context: context || 'No fresh trends found today',
  has_fresh_trends: hasFreshTrends,
  fallback_topic: fallbacks[Math.floor(Math.random() * fallbacks.length)],
  news_titles: newsTitles,
  reddit_topics: redditTopics,
  generated_at: new Date().toISOString()
};

