// Parse Gemini response + inject affiliate boxes + image placeholders
const response = $input.item.json;
let text = response?.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Clean markdown code blocks
text = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let article;
try {
  article = JSON.parse(text);
} catch(e) {
  // Try to extract JSON from response
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    article = JSON.parse(match[0]);
  } else {
    throw new Error('Could not parse Gemini response: ' + text.slice(0, 300));
  }
}

if (!article.title || !article.content) {
  throw new Error('Missing title or content in Gemini response');
}

// Affiliate product mapping (US Amazon - plantsmag-20 tag)
const affiliateMap = {
  'moisture meter': 'https://www.amazon.com/s?k=soil+moisture+meter&tag=plantsmag-20',
  'neem oil': 'https://www.amazon.com/s?k=neem+oil+spray+plants&tag=plantsmag-20',
  'grow light': 'https://www.amazon.com/s?k=grow+lights+indoor+plants&tag=plantsmag-20',
  'humidifier': 'https://www.amazon.com/s?k=humidifier+plants&tag=plantsmag-20',
  'perlite': 'https://www.amazon.com/s?k=horticultural+perlite&tag=plantsmag-20',
  'fungicide': 'https://www.amazon.com/s?k=fungicide+indoor+plants&tag=plantsmag-20',
};

// Replace [PRODUCT: name] placeholders with affiliate boxes
let content = article.content;
content = content.replace(/\[PRODUCT:\s*([^\]]+)\]/gi, (match, productName) => {
  const key = Object.keys(affiliateMap).find(k => productName.toLowerCase().includes(k));
  const url = key ? affiliateMap[key] : 'https://www.amazon.com/s?k=' + encodeURIComponent(productName) + '&tag=plantsmag-20';
  return `<div class="pm-affiliate-box" style="background:linear-gradient(135deg,#f0fff4,#c6f6d5);border-left:4px solid #38a169;padding:20px;margin:30px 0;border-radius:8px;"><p><strong>🛒 Recommended:</strong> <a href="${url}" target="_blank" rel="nofollow noopener" style="color:#276749;font-weight:bold;">${productName} — Check Best Price on Amazon →</a></p></div>`;
});

// Add diagnosis CTA at the end
content += `
<div style="background:linear-gradient(135deg,#ebf8ff,#bee3f8);border-left:4px solid #3182ce;padding:20px;margin:40px 0;border-radius:8px;">
  <h3 style="color:#2b6cb0;margin-top:0;">🔬 Is Your Plant Sick? Get an Instant AI Diagnosis</h3>
  <p>Not sure what's wrong with your plant? Use our <a href="https://plantsmag.com/plant-disease-finder/" style="color:#2b6cb0;font-weight:bold;">AI Plant Disease Finder</a> — upload a photo and get expert diagnosis in seconds.</p>
</div>`;

return {
  title: article.title,
  slug: article.slug || article.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 60),
  meta_description: article.meta_description || '',
  focus_keyword: article.focus_keyword || '',
  content: content,
  word_count: content.split(' ').length
};

